import requests
import os
import zipfile

def task_func(url, destination_directory, headers=None):
    if not url or not isinstance(url, str):
        raise ValueError("URL must be a non-empty string.")
    if not destination_directory or not isinstance(destination_directory, str):
        raise ValueError("Destination directory must be a non-empty string.")

    os.makedirs(destination_directory, exist_ok=True)

    if headers is None:
        headers = {'User-Agent': 'Mozilla/5.0'}

    try:
        response = requests.get(url, headers=headers, stream=True, verify=False)
        response.raise_for_status()
    except requests.RequestException as e:
        raise ConnectionError(f"Failed to download zip from {url}: {e}")

    zip_path = os.path.join(destination_directory, 'downloaded.zip')
    try:
        with open(zip_path, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                f.write(chunk)
    except IOError as e:
        raise IOError(f"Failed to save zip file: {e}")

    extracted_files = []
    try:
        with zipfile.ZipFile(zip_path, 'r') as zip_ref:
            zip_ref.extractall(destination_directory)
            extracted_files = zip_ref.namelist()
    except zipfile.BadZipFile as e:
        raise ValueError(f"Invalid zip file: {e}")
    except Exception as e:
        raise RuntimeError(f"Failed to extract zip file: {e}")

    os.remove(zip_path)
    return extracted_files

